@runtime_checkable
class Streaming(Protocol):
    """A transport that can **push**, which is not all of them.

    Deliberately separate from `Transport` rather than an optional method on
    it. `Bridge` has a websocket; `Proxy` is an in-process call into a
    terminal and has nothing to push with, and a protocol that demanded
    `stream` of both would be satisfied by a `Proxy.stream` that raised - the
    kind of stub that makes a capability check pass and the feature fail at
    the one moment it is used.

    So the check is `isinstance(transport, Streaming)`, and `data.py` refuses
    `quote_source="push"` on a transport that is not, rather than falling back
    to polling. A feed that samples while reporting itself as a push makes
    every measurement taken on it wrong, and nothing about it looks wrong.
    """

    def stream(self, symbols: list[str]) -> Any: ...


#: Every transport name a config may carry. `http` is the default because it
#: is the one the lab box runs and the only one that works through a firewall
#: without a tunnel.
TRANSPORTS: tuple[str, ...] = ("http", "rpyc")

HTTP = "http"
RPYC = "rpyc"


def connect(config: Any) -> Transport:
    """The transport this config asks for, already constructed and not open.

    Both client configs carry the same three fields, so one function serves
    the data side and the order side - and a node that reads the feed over
    HTTP while placing orders over rpyc is expressible, which is occasionally
    what you want: the stream is a sample either way, and an order is where
    the latency is worth paying for.
    """
    name = str(getattr(config, "transport", HTTP) or HTTP).lower()
    if name == HTTP:
        from .bridge import Bridge

        return Bridge(
            config.base_url,
            config.api_key,
            timeout=config.request_timeout,
        )
    if name == RPYC:
        from .proxy import Proxy

        return Proxy(
            host=config.rpyc_host,
            port=config.rpyc_port,
            timeout=config.request_timeout,
            terminal=getattr(config, "terminal_path", None),
            login=getattr(config, "login", 0),
            password=getattr(config, "password", None),
            server=getattr(config, "server", None),
        )
    raise ValueError(
        f"unknown MT5 transport {name!r}: one of {', '.join(TRANSPORTS)}. "
        f"A transport that does not resolve is a client that connects to "
        f"nothing and a node that reports healthy and trades nothing."
    )
